'use strict';
/**
 * dsh-obsidian-math — Obsidian side-panel plugin for the DeepSeek Harness
 * math-memory agent.
 *
 * Generated by scripts/build-obsidian.mjs; edit obsidian/main.template.js
 * and the shared dsh/ files, then rebuild.
 */
const { Plugin, ItemView, Notice, PluginSettingTab, Setting } = require('obsidian');
const { spawn, spawnSync } = require('child_process');
const { existsSync, mkdirSync, writeFileSync, readFileSync, statSync, renameSync } = require('fs');
const { join, dirname } = require('path');
const { homedir } = require('os');
const http = require('http');
const { createServer } = http;

const VIEW_TYPE = 'dsh-obsidian-math-view';
const PRESET_NAME = 'obsidian';
const EMBEDDED_PRESET = JSON.parse("__PRESET_JSON__");
const EMBEDDED_TEMPLATES = JSON.parse("__TEMPLATE_JSON__");

const DEFAULT_SETTINGS = {
  port: 3180,
  dshInstallDir: '',
  dshHome: '',
  autoStart: true,
  autoInit: true,
  autoArchiveEpisodes: true,
  showRibbon: true,
  keepAliveOnUnload: false
};

// ── small helpers ───────────────────────────────────────────────────────────

function ensureFile(target, content, overwrite = false) {
  if (!overwrite && existsSync(target)) return false;
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content, 'utf8');
  return true;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Probe the local dsh web server with Node's http client. Do NOT use
 * browser `fetch` here: Obsidian's CSP can block renderer-side requests to
 * http://127.0.0.1, which previously made a healthy service look dead.
 */
function probeService(port, timeoutMs = 1500) {
  return new Promise((resolve) => {
    let settled = false;
    const finish = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    const request = http.get({ host: '127.0.0.1', port, path: '/', timeout: timeoutMs }, (response) => {
      response.resume();
      finish(response.statusCode >= 200 && response.statusCode < 500);
    });
    request.on('error', () => finish(false));
    request.on('timeout', () => {
      request.destroy();
      finish(false);
    });
  });
}

/**
 * The dsh server is a Node program. `process.execPath` inside Obsidian points
 * at the Electron binary (obsidian.exe), never at node, so we spawn `node`
 * from PATH. DSH_NODE_BIN allows an explicit override.
 */
function nodeExecutable() {
  const override = process.env.DSH_NODE_BIN?.trim();
  if (override) return override;
  return process.platform === 'win32' ? 'node.exe' : 'node';
}

/**
 * Minimal loopback HTTP server that turns agent replies' note links into
 * Obsidian jumps. The dsh agent is told (via env) to render note references
 * as `[title](http://127.0.0.1:<port>/open?path=<vault-relative path>)`;
 * clicking such a link inside the iframe hits this server, which opens the
 * note in Obsidian and navigates the iframe back to dsh.
 */
class LinkServer {
  constructor(plugin) {
    this.plugin = plugin;
    this.server = null;
    this.port = 0;
  }

  start() {
    this.server = createServer((req, res) => {
      const finish = (status, body, html = false) => {
        res.writeHead(status, { 'content-type': html ? 'text/html; charset=utf-8' : 'text/plain; charset=utf-8' });
        res.end(body);
      };
      let url;
      try {
        url = new URL(req.url ?? '/', 'http://127.0.0.1');
      } catch {
        finish(400, 'bad request');
        return;
      }
      if (url.pathname !== '/open') {
        finish(404, 'not found');
        return;
      }
      const rawPath = url.searchParams.get('path') ?? url.searchParams.get('note') ?? '';
      const notePath = decodeURIComponent(rawPath).trim();
      if (notePath === '' || notePath.length > 2000) {
        finish(400, 'missing path');
        return;
      }
      try {
        this.plugin.app.workspace.openLinkText(notePath, '', false);
      } catch (error) {
        finish(500, String(error));
        return;
      }
      const display = notePath.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
      finish(200, `<!doctype html><meta charset="utf-8"><body style="font-family:sans-serif;padding:24px"><p>已在 Obsidian 中打开：<code>${display}</code></p><script>setTimeout(function(){history.back()},400)</script></body>`, true);
    });
    this.server.listen(0, '127.0.0.1', () => {
      const address = this.server.address();
      this.port = typeof address === 'object' && address !== null ? address.port : 0;
      this.plugin.service?.appendLog(`链接跳转服务已启动：http://127.0.0.1:${this.port}`);
    });
  }

  get baseUrl() {
    return this.port > 0 ? `http://127.0.0.1:${this.port}` : '';
  }

  stop() {
    if (this.server !== null) {
      this.server.close();
      this.server = null;
      this.port = 0;
    }
  }
}

// ── dsh detection ───────────────────────────────────────────────────────────

function validInstallDir(dir) {
  if (!dir) return null;
  const tryRoot = (root) => {
    try {
      const manifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
      if (manifest.name !== '@deepseek-ai/dsh') return null;
      return { installDir: root, script: join(root, 'lib', 'bin.js') };
    } catch {
      return null;
    }
  };
  // npm-global layout: <dir> itself is @deepseek-ai/dsh
  const direct = tryRoot(dir);
  if (direct) return direct;
  // custom layout: <dir>/dsh is the package (e.g. E:\software\deepseek-harness)
  const nested = tryRoot(join(dir, 'dsh'));
  if (nested) return nested;
  return null;
}

function parseLauncher(cmdPath) {
  try {
    const content = readFileSync(cmdPath, 'utf8');
    const dp0 = dirname(cmdPath);
    const match = /node\s+"([^"]+)"/i.exec(content);
    if (match) {
      let script = match[1].trim();
      if (script.startsWith('%~dp0')) script = join(dp0, script.slice('%~dp0'.length));
      if (script.toLowerCase().endsWith('bin.js') || /lib[\\/]bin\.js/i.test(script)) {
        return { installDir: dirname(dirname(script)), script };
      }
    }
    if (/dsh[\\/]lib[\\/]bin\.js/.test(content)) {
      return { installDir: dp0, script: join(dp0, 'dsh', 'lib', 'bin.js') };
    }
    return { installDir: dp0, script: '' };
  } catch {
    return null;
  }
}

function detectInstallCandidates(settings) {
  const candidates = [];
  if (settings.dshInstallDir) candidates.push(settings.dshInstallDir);
  if (process.env.DSH_HOME) candidates.push(dirname(process.env.DSH_HOME));
  const appData = process.env.APPDATA || join(homedir(), 'AppData', 'Roaming');
  candidates.push(join(appData, 'npm', 'node_modules', '@deepseek-ai', 'dsh'));
  return candidates;
}

function detectFromShell() {
  const result = [];
  let command;
  if (process.platform === 'win32') {
    command = spawnSync('where', ['dsh'], { encoding: 'utf8', timeout: 6000, windowsHide: true });
  } else {
    command = spawnSync('which', ['dsh'], { encoding: 'utf8', timeout: 6000 });
  }
  if (command.status !== 0 || !command.stdout) return result;
  for (const raw of command.stdout.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === '') continue;
    const parsed = parseLauncher(line);
    if (parsed) result.push(parsed);
    result.push({ installDir: dirname(line), script: '' });
  }
  return result;
}

function detectDsh(settings) {
  for (const dir of detectInstallCandidates(settings)) {
    const valid = validInstallDir(dir);
    if (valid) return valid;
  }
  for (const parsed of detectFromShell()) {
    const valid = validInstallDir(parsed.installDir);
    if (valid) return valid;
    if (parsed.script) return { installDir: parsed.installDir, script: parsed.script };
  }
  return null;
}

function detectDshHome(settings, detected) {
  if (settings.dshHome) return settings.dshHome;
  if (process.env.DSH_HOME) return process.env.DSH_HOME;
  if (detected?.installDir && existsSync(join(detected.installDir, '.dsh'))) {
    return join(detected.installDir, '.dsh');
  }
  return join(homedir(), '.dsh');
}

// ── dsh service manager ─────────────────────────────────────────────────────

class DshService {
  constructor(plugin) {
    this.plugin = plugin;
    this.child = null;
    this.status = 'unknown';
    this.logLines = [];
    this.listeners = new Set();
    this.cachedLocation = undefined;
  }

  onChange(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  setStatus(status) {
    if (this.status === status) return;
    this.status = status;
    for (const listener of this.listeners) listener(status);
  }

  appendLog(text) {
    for (const line of String(text).split(/\r?\n/)) {
      if (line.trim() === '') continue;
      this.logLines.push(line);
      if (this.logLines.length > 600) this.logLines.shift();
    }
  }

  location(force = false) {
    if (!force && this.cachedLocation !== undefined) return this.cachedLocation;
    const detected = detectDsh(this.plugin.settings);
    this.cachedLocation = detected === null ? null : {
      installDir: detected.installDir,
      script: detected.script,
      home: detectDshHome(this.plugin.settings, detected)
    };
    return this.cachedLocation;
  }

  async ensureStarted() {
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.setStatus('running');
      return;
    }
    return this.start();
  }

  async start() {
    if (this.child !== null && this.child.exitCode === null) return;
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.setStatus('running');
      return;
    }
    const location = this.location();
    if (location === null) {
      this.setStatus('missing-dsh');
      throw new Error('未找到 dsh。请打开插件设置，点击“自动检测”，或先安装 DeepSeek Harness。');
    }
    const patchPath = this.plugin.settings.autoInit
      ? ensureObsidianPatch(location)
      : join(location.home, 'profiles', PRESET_NAME, 'obsidian.patch.yml');
    const patchArgs = existsSync(patchPath) ? ['--patch', patchPath] : [];
    const vaultPath = this.plugin.app.vault.adapter.getBasePath();
    const linkBaseUrl = this.plugin.linkServer?.baseUrl ?? '';
    const env = {
      ...process.env,
      DSH_HOME: location.home,
      DSH_OBSIDIAN_VAULT: vaultPath,
      DSH_SESSIONS_ROOT: join(location.home, 'sessions'),
      ...(linkBaseUrl === '' ? {} : { DSH_OBSIDIAN_LINK_URL: linkBaseUrl })
    };
    const args = location.script
      ? [location.script, '--profile', PRESET_NAME, ...patchArgs, '--port', String(this.plugin.settings.port)]
      : ['--profile', PRESET_NAME, ...patchArgs, '--port', String(this.plugin.settings.port)];
    const executable = location.script ? nodeExecutable() : 'dsh';
    // Without a resolved script we rely on the dsh launcher; Windows needs a
    // shell to execute .cmd shims.
    const shell = !location.script && process.platform === 'win32';
    this.setStatus('starting');
    this.appendLog(`启动：${executable} ${args.join(' ')}`);
    const child = spawn(executable, args, { env, windowsHide: true, shell, stdio: ['ignore', 'pipe', 'pipe'] });
    this.child = child;
    let spawnError = null;
    child.stdout.on('data', (chunk) => this.appendLog(chunk));
    child.stderr.on('data', (chunk) => this.appendLog(chunk));
    // Without this handler a missing `node` binary throws an uncaught
    // ChildProcess 'error' event and can take the whole plugin down.
    child.on('error', (error) => {
      spawnError = error;
      this.appendLog(`启动失败：${String(error)}`);
      if (this.child === child) this.child = null;
      this.setStatus('error');
    });
    child.on('exit', (code) => {
      this.appendLog(`dsh 已退出，退出码 ${code}`);
      if (this.child === child) this.child = null;
      if (this.status !== 'stopping' && spawnError === null) this.setStatus(code === 0 ? 'stopped' : 'error');
    });
    for (let attempt = 0; attempt < 60; attempt += 1) {
      await sleep(750);
      if (await probeService(this.plugin.settings.port, 1000)) {
        this.setStatus('running');
        return;
      }
      if (this.child === null || this.child.exitCode !== null) break;
    }
    this.setStatus('error');
    throw new Error(`dsh 服务未能在端口 ${this.plugin.settings.port} 上启动。${this.logLines.slice(-3).join(' | ')}`);
  }

  async stop() {
    this.setStatus('stopping');
    const child = this.child;
    this.child = null;
    if (child !== null && child.exitCode === null) {
      const exited = new Promise((resolve) => {
        child.once('exit', resolve);
        setTimeout(resolve, 1500);
      });
      child.kill();
      await exited;
    }
    this.setStatus('stopped');
  }

  async restart() {
    await this.stop();
    await sleep(500);
    return this.start();
  }
}

// ── embedded configuration bootstrap ────────────────────────────────────────

/**
 * Plugin-owned profile overlay: always refresh the auto-workspace host plugin
 * and return the `--patch` path handed to the dsh launcher.
 */
function ensureObsidianPatch(location) {
  const profileRoot = join(location.home, 'profiles', PRESET_NAME);
  ensureFile(join(profileRoot, 'obsidian-workspace.mjs'), EMBEDDED_PRESET['profile-obsidian-workspace.mjs'], true);
  const patchPath = join(profileRoot, 'obsidian.patch.yml');
  ensureFile(patchPath, EMBEDDED_PRESET['profile-obsidian.patch.yml'], true);
  return patchPath;
}

function bootstrapDshConfig(plugin, force = false) {
  const location = plugin.service.location();
  if (location === null) throw new Error('未检测到 dsh。请先在设置中配置 dsh 安装目录。');
  const home = location.home;
  const presetRoot = join(home, '.agent-presets', PRESET_NAME);
  const profileRoot = join(home, 'profiles', PRESET_NAME);
  const written = [];

  // Code always refreshes; user-editable files are preserved unless forced.
  if (ensureFile(join(presetRoot, 'obsidian-memory.mjs'), EMBEDDED_PRESET['obsidian-memory.mjs'], true)) written.push('preset/obsidian-memory.mjs');
  if (ensureFile(join(presetRoot, 'obsidian-notes.mjs'), EMBEDDED_PRESET['obsidian-notes.mjs'], true)) written.push('preset/obsidian-notes.mjs');
  if (ensureFile(join(presetRoot, 'preset.yml'), EMBEDDED_PRESET['preset.yml'], force)) written.push('preset/preset.yml');
  if (ensureFile(join(presetRoot, 'agent.cordis.yml'), EMBEDDED_PRESET['agent.cordis.yml'], force)) written.push('preset/agent.cordis.yml');
  if (ensureFile(join(profileRoot, 'package.json'), EMBEDDED_PRESET['profile-package.json'], force)) written.push('profile/package.json');
  if (ensureFile(join(profileRoot, 'cordis.yml'), EMBEDDED_PRESET['profile-cordis.yml'], true)) written.push('profile/cordis.yml');
  if (ensureFile(join(profileRoot, 'cordis.patch.yml'), EMBEDDED_PRESET['profile-cordis.patch.yml'], force)) written.push('profile/cordis.patch.yml');
  if (ensureFile(join(profileRoot, 'pnpm-workspace.yaml'), EMBEDDED_PRESET['profile-pnpm-workspace.yaml'], force)) written.push('profile/pnpm-workspace.yaml');
  if (ensureFile(join(profileRoot, 'obsidian-workspace.mjs'), EMBEDDED_PRESET['profile-obsidian-workspace.mjs'], true)) written.push('profile/obsidian-workspace.mjs');
  if (ensureFile(join(profileRoot, 'obsidian.patch.yml'), EMBEDDED_PRESET['profile-obsidian.patch.yml'], true)) written.push('profile/obsidian.patch.yml');
  return { home, written };
}

function bootstrapVaultTemplates(plugin, force = false) {
  const vault = plugin.app.vault.adapter.getBasePath();
  const mapping = [
    ['AGENTS.md', join(vault, 'AGENTS.md')],
    ['profile.md', join(vault, '.deepseek', 'memory', 'profile.md')],
    ['topics-index.md', join(vault, '.deepseek', 'memory', 'topics', 'index.md')],
    ['records-readme.md', join(vault, '.deepseek', 'memory', 'records', '_README.md')],
    ['records-index.md', join(vault, '.deepseek', 'memory', 'records', 'index.md')],
    ['theorems-readme.md', join(vault, '.deepseek', 'memory', 'theorems', '_README.md')],
    ['theorems-index.md', join(vault, '.deepseek', 'memory', 'theorems', 'index.md')],
    ['templates-readme.md', join(vault, '.deepseek', 'memory', 'templates', '_README.md')],
    ['templates-index.md', join(vault, '.deepseek', 'memory', 'templates', 'index.md')],
    ['episodes-readme.md', join(vault, '.deepseek', 'memory', 'episodes', '_README.md')],
    ['episodes-index.md', join(vault, '.deepseek', 'memory', 'episodes', 'index.md')],
    ['inbox-readme.md', join(vault, '.deepseek', 'inbox', '_README.md')],
    ['inbox-index.md', join(vault, '.deepseek', 'inbox', 'index.md')]
  ];
  const written = [];
  for (const [key, target] of mapping) {
    if (ensureFile(target, EMBEDDED_TEMPLATES[key], force)) written.push(target);
  }
  return { vault, written };
}

/**
 * Host-side memory maintenance: move episode files older than `maxDays` into
 * `episodes/archive/` and update the episode index links. The agent has no
 * delete/move tools, so the Obsidian plugin owns this one lifecycle operation.
 */
function archiveOldEpisodes(plugin, maxDays = 90) {
  const vault = plugin.app.vault.adapter.getBasePath();
  const episodesDir = join(vault, '.deepseek', 'memory', 'episodes');
  if (!existsSync(episodesDir)) return { moved: 0 };
  const archiveDir = join(episodesDir, 'archive');
  const cutoff = Date.now() - maxDays * 86400000;
  const moved = [];
  let entries;
  try {
    entries = readdirSync(episodesDir, { withFileTypes: true });
  } catch {
    return { moved: 0 };
  }
  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith('.md') || entry.name === 'index.md' || entry.name.startsWith('_')) continue;
    const source = join(episodesDir, entry.name);
    let stats;
    try {
      stats = statSync(source);
    } catch {
      continue;
    }
    if (stats.mtimeMs >= cutoff) continue;
    try {
      mkdirSync(archiveDir, { recursive: true });
      let target = join(archiveDir, entry.name);
      let suffix = 1;
      while (existsSync(target)) {
        suffix += 1;
        target = join(archiveDir, entry.name.replace(/\.md$/, `-${suffix}.md`));
      }
      renameSync(source, target);
      // Obsidian wikilinks always use forward slashes, even on Windows.
      const archivedName = suffix === 1 ? entry.name : entry.name.replace(/\.md$/, `-${suffix}.md`);
      moved.push({ name: entry.name, linkName: `archive/${archivedName}` });
    } catch {
      // Leave the file in place on any maintenance failure.
    }
  }
  if (moved.length > 0) {
    const indexPath = join(episodesDir, 'index.md');
    if (existsSync(indexPath)) {
      try {
        let indexText = readFileSync(indexPath, 'utf8');
        for (const item of moved) {
          const oldStem = item.name.replace(/\.md$/, '');
          const newStem = item.linkName.replace(/\.md$/, '');
          indexText = indexText.replaceAll(`[[${oldStem}|`, `[[${newStem}|`);
          indexText = indexText.replaceAll(`[[${oldStem}]]`, `[[${newStem}]]`);
        }
        writeFileSync(indexPath, indexText, 'utf8');
      } catch {
        // Index update is best-effort; moved files are already safe.
      }
    }
  }
  return { moved: moved.length };
}

// ── sidebar view ────────────────────────────────────────────────────────────

class DshMathView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.offStatus = null;
    this.iframe = null;
  }

  getViewType() {
    return VIEW_TYPE;
  }

  getDisplayText() {
    return 'DSH数学笔记助手';
  }

  getIcon() {
    return 'message-square';
  }

  async onOpen() {
    this.contentEl.empty();
    this.contentEl.addClass('dsh-obsidian-math-view');
    this.statusRow = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-status' });
    this.body = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-body' });
    this.offStatus = this.plugin.service.onChange((status) => this.render(status));
    const status = await this.plugin.service.ensureStarted().then(() => this.plugin.service.status).catch(() => this.plugin.service.status);
    this.render(status);
  }

  render(status) {
    if (this.statusRow === undefined) return;
    if (status === 'running') {
      this.statusRow.empty();
      this.statusRow.style.display = 'none';
      const expectedSrc = `http://127.0.0.1:${this.plugin.settings.port}/`;
      if (this.iframe === null) {
        this.iframe = this.body.createEl('iframe', {
          cls: 'dsh-obsidian-math-iframe',
          attr: { src: expectedSrc }
        });
      } else if (this.iframe.getAttribute('src') !== expectedSrc) {
        this.iframe.setAttribute('src', expectedSrc);
      }
      return;
    }
    this.statusRow.style.display = '';
    if (this.iframe !== null) {
      this.iframe.remove();
      this.iframe = null;
    }
    this.statusRow.empty();
    const message = {
      starting: '正在启动 DeepSeek Harness 服务…',
      'missing-dsh': '未找到 dsh（DeepSeek Harness）。请打开插件设置并检测 dsh 安装路径。',
      error: 'dsh 服务启动失败。请打开插件设置查看日志。',
      stopped: 'dsh 服务已停止。',
      stopping: '正在停止服务…',
      unknown: '服务状态未知。'
    }[status] ?? '服务状态未知。';
    this.statusRow.setText(message);
    const actions = this.statusRow.createDiv({ cls: 'dsh-obsidian-math-actions' });
    const retry = actions.createEl('button', { text: '重试' });
    retry.addEventListener('click', async () => {
      this.render('starting');
      await this.plugin.service.ensureStarted().catch((error) => new Notice(String(error)));
      this.render(this.plugin.service.status);
    });
    const settings = actions.createEl('button', { text: '打开设置' });
    settings.addEventListener('click', () => this.plugin.openSettings());
  }

  async onClose() {
    if (this.offStatus !== null) this.offStatus();
  }
}

// ── plugin ──────────────────────────────────────────────────────────────────

class DshObsidianMathPlugin extends Plugin {
  async onload() {
    await this.loadSettings();
    this.service = new DshService(this);
    this.linkServer = new LinkServer(this);
    this.linkServer.start();
    this.registerView(VIEW_TYPE, (leaf) => new DshMathView(leaf, this));
    if (this.settings.showRibbon) {
      this.addRibbonIcon('message-square', '打开 DSH数学笔记助手', () => this.activateView());
    }
    this.addCommand({
      id: 'open-dsh-math-assistant',
      name: '打开 DSH数学笔记助手',
      callback: () => this.activateView()
    });
    this.addCommand({
      id: 'start-dsh-service',
      name: '启动 DSH 服务',
      callback: async () => {
        try {
          await this.service.start();
          new Notice('DSH 服务已运行');
        } catch (error) {
          new Notice(String(error));
        }
      }
    });
    this.addCommand({
      id: 'stop-dsh-service',
      name: '停止 DSH 服务',
      callback: async () => {
        await this.service.stop();
        new Notice('DSH 服务已停止');
      }
    });
    this.addSettingTab(new DshObsidianSettingTab(this.app, this));
    if (this.settings.autoInit) {
      this.app.workspace.onLayoutReady(() => {
        try {
          bootstrapDshConfig(this, false);
          bootstrapVaultTemplates(this, false);
        } catch (error) {
          new Notice(`dsh-obsidian-math: ${String(error)}`);
        }
      });
    }
    if (this.settings.autoArchiveEpisodes) {
      this.app.workspace.onLayoutReady(() => {
        try {
          const result = archiveOldEpisodes(this, 90);
          if (result.moved > 0) new Notice(`记忆维护：已归档 ${result.moved} 个旧事件文件`);
        } catch (error) {
          new Notice(`记忆维护失败：${String(error)}`);
        }
      });
    }
    if (this.settings.autoStart) {
      this.app.workspace.onLayoutReady(() => {
        setTimeout(() => {
          this.service.ensureStarted().catch(() => {});
        }, 1200);
      });
    }
  }

  async activateView() {
    const { workspace } = this.app;
    let leaf = workspace.getLeavesOfType(VIEW_TYPE)[0];
    if (!leaf) {
      if (typeof workspace.getRightLeaf === 'function') {
        leaf = workspace.getRightLeaf(false);
      } else {
        leaf = workspace.getLeaf('tab');
      }
      await leaf.setViewState({ type: VIEW_TYPE, active: true });
    }
    if (typeof workspace.revealLeaf === 'function') await workspace.revealLeaf(leaf);
    else workspace.setActiveLeaf(leaf);
  }

  openSettings() {
    const setting = this.app.setting;
    if (!setting) return;
    try {
      setting.open();
    } catch {
      // ignored; openTabById below is the important part
    }
    try {
      setting.openTabById(this.manifest.id);
    } catch {
      // older Obsidian: the settings root is already open
    }
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }

  async saveSettings() {
    await this.saveData(this.settings);
  }

  onunload() {
    this.linkServer?.stop();
    if (this.service?.child !== null && !this.settings.keepAliveOnUnload) {
      this.service?.stop();
    }
  }
}

module.exports = DshObsidianMathPlugin;

// ── settings tab ────────────────────────────────────────────────────────────

class DshObsidianSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl('h2', { text: 'DSH数学笔记助手' });
    containerEl.createEl('p', { text: `版本 ${this.plugin.manifest?.version ?? ''}` });
    containerEl.createEl('p', { text: '在 Obsidian 右侧栏嵌入 DeepSeek Harness 数学记忆助手。插件会自动启动 dsh 服务，无需额外打开命令行窗口。' });
    containerEl.createEl('p', { cls: 'dsh-obsidian-math-security-note', text: '🔒 安全模式：助手只能写当前 vault 内的文件；权限升级审批默认关闭，不会弹出“是否提权”的窗口；工具集中没有删除类工具。' });
    containerEl.createEl('p', { cls: 'dsh-obsidian-math-security-note', text: '🧭 适用范围：面向数学类知识（数学、统计学笔记与数学思维方式）设计，其他领域的知识可能需要不同的记忆架构。当前为试做型（0.3.x），记忆架构尚未经过长期使用测试，后续会继续演进。' });

    new Setting(containerEl)
      .setName('端口')
      .setDesc('dsh 网页服务的本地端口。默认 3180，与默认 dsh web 的 3080 互不冲突。')
      .addText((text) => text
        .setPlaceholder('3180')
        .setValue(String(this.plugin.settings.port))
        .onChange(async (value) => {
          const port = Number.parseInt(value, 10);
          if (Number.isInteger(port) && port > 0 && port < 65536) {
            this.plugin.settings.port = port;
            await this.plugin.saveSettings();
          }
        }));

    const location = this.plugin.service.location();
    new Setting(containerEl)
      .setName('dsh 安装目录')
      .setDesc(location ? `已检测到：${location.installDir}` : '尚未检测到。可点击“自动检测”，或手动填写目录后回车。')
      .addText((text) => text
        .setPlaceholder('留空则自动检测')
        .setValue(this.plugin.settings.dshInstallDir)
        .onChange(async (value) => {
          this.plugin.settings.dshInstallDir = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }))
      .addButton((button) => button.setButtonText('自动检测').onClick(async () => {
        const found = this.plugin.service.location(true);
        if (found === null) {
          new Notice('未找到 dsh。请先安装 DeepSeek Harness，或手动填写安装目录。');
        } else {
          this.plugin.settings.dshInstallDir = found.installDir;
          await this.plugin.saveSettings();
          new Notice(`已检测到 dsh：${found.installDir}`);
          this.display();
        }
      }));

    new Setting(containerEl)
      .setName('DSH_HOME')
      .setDesc(location ? `已自动探测：${location.home}（可直接修改）` : 'dsh 主目录（preset、profile、会话日志所在处）。留空则自动探测。')
      .addText((text) => text
        .setPlaceholder('留空则自动探测')
        .setValue(location?.home ?? this.plugin.settings.dshHome)
        .onChange(async (value) => {
          this.plugin.settings.dshHome = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName('启动 Obsidian 时自动启动服务')
      .setDesc('打开 Obsidian 后自动拉起 dsh 服务，无需手动操作。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoStart).onChange(async (value) => {
        this.plugin.settings.autoStart = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('自动初始化 dsh 配置与记忆模板')
      .setDesc('首次运行时自动补齐 preset、profile 与 vault 内的记忆模板（只补缺失文件，不覆盖已有修改）。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoInit).onChange(async (value) => {
        this.plugin.settings.autoInit = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('启动时自动归档旧事件（超过 90 天）')
      .setDesc('把过旧的事件卡移入 episodes/archive/ 并更新索引——由插件执行，agent 本身没有删除/移动工具。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoArchiveEpisodes).onChange(async (value) => {
        this.plugin.settings.autoArchiveEpisodes = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('显示侧边栏按钮')
      .setDesc('在 Obsidian 左侧 ribbon 显示一键打开按钮。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.showRibbon).onChange(async (value) => {
        this.plugin.settings.showRibbon = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('关闭 Obsidian 时保留服务')
      .setDesc('默认关闭：插件退出时会停止它自己启动的 dsh 服务。')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.keepAliveOnUnload).onChange(async (value) => {
        this.plugin.settings.keepAliveOnUnload = value;
        await this.plugin.saveSettings();
      }));

    containerEl.createEl('h3', { text: '配置' });
    const configRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const initButton = configRow.createEl('button', { text: '初始化 dsh 配置与 vault 模板' });
    initButton.addEventListener('click', async () => {
      try {
        const dsh = bootstrapDshConfig(this.plugin, false);
        const vault = bootstrapVaultTemplates(this.plugin, false);
        new Notice(`dsh 配置已就绪（${dsh.written.length} 个文件）。vault 模板：${vault.written.length} 个。`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const forceButton = configRow.createEl('button', { text: '强制重装 dsh 配置' });
    forceButton.addEventListener('click', async () => {
      try {
        const result = bootstrapDshConfig(this.plugin, true);
        new Notice(`dsh 配置已重装到 ${result.home}`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const archiveButton = configRow.createEl('button', { text: '立即归档旧事件（>90 天）' });
    archiveButton.addEventListener('click', () => {
      try {
        const result = archiveOldEpisodes(this.plugin, 90);
        new Notice(result.moved > 0 ? `已归档 ${result.moved} 个旧事件文件` : '没有需要归档的旧事件');
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });

    containerEl.createEl('h3', { text: '服务' });
    const serviceRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const startButton = serviceRow.createEl('button', { text: '启动服务' });
    startButton.addEventListener('click', async () => {
      await this.plugin.service.start().catch((error) => new Notice(String(error)));
      this.display();
    });
    const stopButton = serviceRow.createEl('button', { text: '停止服务' });
    stopButton.addEventListener('click', async () => {
      await this.plugin.service.stop();
      this.display();
    });
    const restartButton = serviceRow.createEl('button', { text: '重启服务' });
    restartButton.addEventListener('click', async () => {
      await this.plugin.service.restart().catch((error) => new Notice(String(error)));
      this.display();
    });
    const statusLabels = {
      running: '运行中',
      starting: '启动中',
      stopped: '已停止',
      stopping: '停止中',
      'missing-dsh': '未找到 dsh',
      error: '错误',
      unknown: '未知'
    };
    serviceRow.createEl('span', { text: ` 状态：${statusLabels[this.plugin.service.status] ?? this.plugin.service.status}` });

    const log = this.plugin.service.logLines.join('\n');
    if (log !== '') {
      containerEl.createEl('h3', { text: `最近服务日志（共 ${this.plugin.service.logLines.length} 行，可滚动）` });
      const copyLog = containerEl.createEl('button', { text: '复制全部日志' });
      copyLog.addEventListener('click', async () => {
        try {
          await navigator.clipboard.writeText(log);
          new Notice('日志已复制到剪贴板');
        } catch {
          new Notice('复制失败，请手动选择日志文本');
        }
      });
      containerEl.createEl('pre', { text: log, cls: 'dsh-obsidian-math-log' });
    }
  }
}
